  position: absolute;
  top: 10%;
  left: 50%;
  transform: translateX(-50%);
  width: 750px;
  height: 500px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(37, 99, 235, 0.16) 0%, transparent 70%);
  pointer-events: none;
  filter: blur(24px);
}

.vg-hero__inner {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin: 0 auto;
  text-align: center;
}

.vg-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 1rem;
  background: rgba(37, 99, 235, 0.08);
  border: 1px solid rgba(37, 99, 235, 0.22);
  border-radius: 999px;
  color: #e4e4e7;
  font-size: 0.82rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.vg-hero__badge-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #2563eb;
  box-shadow: 0 0 8px #2563eb;
}

.vg-hero__title {
  font-family: 'Inter', sans-serif;
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  font-weight: 800;
  color: #fafafa;
  line-height: 1.12;
  letter-spacing: -0.02em;
  margin: 0 0 1.5rem;
}

.vg-hero__subtitle {
  font-size: 1.15rem;
  color: #a1a1aa;
  line-height: 1.7;
  max-width: 640px;
  margin: 0 auto 2.5rem;
}

.vg-hero__actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.vg-hero__btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background: #2563eb;
  color: #0c0d12;
  font-weight: 700;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.vg-hero__btn-primary:hover {
  background: #1d4ed8;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(37, 99, 235, 0.35);
}

.vg-hero__btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background: rgba(37, 99, 235, 0.04);
  color: #fafafa;
  border: 1px solid rgba(37, 99, 235, 0.32);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.vg-hero__btn-secondary:hover {
  border-color: #2563eb;
  color: #2563eb;
  transform: translateY(-2px);
}

.vg-hero__metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  max-width: 640px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.vg-hero__metric {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.vg-hero__metric-value {
  font-family: 'Inter', sans-serif;
  font-size: 1.6rem;
  font-weight: 700;
  color: #fafafa;
}

.vg-hero__metric-label {
  font-size: 0.8rem;
  color: #71717a;
}

@media (max-width: 600px) {
  .vg-hero__metrics { grid-template-columns: 1fr; gap: 1rem; }
}

@media (prefers-reduced-motion: reduce) {
  .vg-hero,
  .vg-hero__btn-primary,
  .vg-hero__btn-secondary,
  .vg-hero__atmosphere {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }
}

