.tw-hero__atmosphere {
  position: absolute;
  top: 10%;
  left: 50%;
  transform: translateX(-50%);
  width: 750px;
  height: 500px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(19, 179, 130, 0.16) 0%, transparent 70%);
