  filter: blur(24px);
}

.tw-hero__inner {
  position: relative;
  z-index: 1;
  max-width: 880px;
  margin: 0 auto;
  text-align: center;
}

.tw-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
