  margin-bottom: 1.5rem;
}

.tw-hero__badge-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #13b382;
  box-shadow: 0 0 8px #13b382;
}

.tw-hero__title {
  font-family: 'Outfit', sans-serif;
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  font-weight: 800;
  color: #fafafa;
  line-height: 1.12;
  letter-spacing: -0.02em;
  margin: 0 0 1.5rem;
}

.tw-hero__subtitle {
  font-size: 1.15rem;
  color: #a1a1aa;
  line-height: 1.7;
  max-width: 640px;
  margin: 0 auto 2.5rem;
}

.tw-hero__actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.tw-hero__btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background: #13b382;
  color: #0c0d12;
  font-weight: 700;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.tw-hero__btn-primary:hover {
  background: #059669;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(19, 179, 130, 0.35);
}

.tw-hero__btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2.2rem;
  background: rgba(19, 179, 130, 0.04);
  color: #fafafa;
  border: 1px solid rgba(19, 179, 130, 0.32);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.tw-hero__btn-secondary:hover {
  border-color: #13b382;
  color: #13b382;
  transform: translateY(-2px);
}

.tw-hero__metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  max-width: 640px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.tw-hero__metric {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.tw-hero__metric-value {
  font-family: 'Outfit', sans-serif;
  font-size: 1.6rem;
  font-weight: 700;
  color: #fafafa;
}

.tw-hero__metric-label {
  font-size: 0.8rem;
  color: #71717a;
}

@media (max-width: 600px) {
  .tw-hero__metrics { grid-template-columns: 1fr; gap: 1rem; }
}

@media (prefers-reduced-motion: reduce) {
  .tw-hero,
  .tw-hero__btn-primary,
  .tw-hero__btn-secondary,
  .tw-hero__atmosphere {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }
}

