import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`mr-header${scrolled ? ' mr-header--scrolled' : ''}`} role="banner">
      <div className="mr-header__inner">
        <a href="#" className="mr-header__logo" aria-label="Meridian Coffee Roasters Home">
          Meridian Coffee Roasters
        </a>

        <nav className="mr-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="mr-header__link">Home</a>
          <a href="#microlots" className="mr-header__link">Current Microlots</a>
          <a href="#footer" className="mr-header__link">Contact</a>
        </nav>

        <div className="mr-header__actions">
          <a href="mailto:beans@meridianroasters.com" className="mr-header__cta">
            Subscribe to Roaster's Choice
          </a>
          <button
            type="button"
            className="mr-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="mr-header__bar" />
            <span className="mr-header__bar" />
            <span className="mr-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="mr-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#microlots" onClick={() => setMenuOpen(false)}>Current Microlots</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

