            <span className="mr-tabs__panel-index">Tier 0{activeTab + 1}</span>
          </div>
          <h3 className="mr-tabs__panel-title">{ITEMS[activeTab]?.title}</h3>
          <p className="mr-tabs__panel-desc">{ITEMS[activeTab]?.desc}</p>
          <div className="mr-tabs__panel-footer">
