              Inquire About {ITEMS[activeTab]?.title}
            </a>
          </div>
        </div>

        <div className="mr-tabs__grid">
          {ITEMS.map((item, idx) => (
            <div
              key={item.title}
              className={`mr-tabs__card${activeTab === idx ? ' mr-tabs__card--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              <div className="mr-tabs__card-top">
                <span className="mr-tabs__card-num">0{idx + 1}</span>
                <span className="mr-tabs__card-tag">{item.tag}</span>
