  letter-spacing: -0.02em;
}

.cne-header__nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.cne-header__link {
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.75));
  text-decoration: none;
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.15s ease;
}

.cne-header__link:hover {
  color: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
}

.cne-header__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.cne-header__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.55rem 1.35rem;
  background: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.cne-header__cta:hover {
  opacity: 0.92;
  transform: translateY(-1px);
}

.cne-header__toggle {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.cne-header__bar {
  width: 20px;
  height: 2px;
  background: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 0;
}

.cne-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 1.5rem 1.5rem;
  background: var(--surface-obsidian, var(--color-obsidian, #080b14));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 1rem;
}

.cne-header__mobile-link {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 1rem;
}

.cne-header__mobile-cta {
  display: inline-block;
  text-align: center;
  padding: 0.75rem 1.5rem;
  background: var(--color-iridescent-fade, var(--accent-color, #38bdf8));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 12px;
  text-decoration: none;
  font-weight: 600;
  margin-top: 0.5rem;
}

@media (max-width: 768px) {
  .cne-header__nav { display: none; }
  .cne-header__toggle { display: flex; }
}
