  border-radius: 0;
}

.asa-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 1.5rem 1.5rem;
  background: var(--surface-obsidian, var(--color-obsidian, #080b14));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 1rem;
}

.asa-header__mobile-link {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 1rem;
}

.asa-header__mobile-cta {
  display: inline-block;
  text-align: center;
  padding: 0.75rem 1.5rem;
  background: var(--color-iridescent-fade, var(--accent-color, #a855f7));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 12px;
