.hir-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  width: 100%;
  background: var(--surface-obsidian, var(--color-obsidian, var(--bg-color, #ffffff)));
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: all 0.25s ease;
}

.hir-header--scrolled {
  background: var(--surface-obsidian, var(--color-obsidian, #ffffff));
  border-bottom-color: rgba(255, 255, 255, 0.18);
}

.hir-header__inner {
  max-width: var(--page-max-width, 1140px);
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.hir-header__logo {
  font-family: var(--font-heading, 'Space Grotesk', sans-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-paper, var(--text-color, #ffffff));
  text-decoration: none;
  letter-spacing: -0.02em;
}

.hir-header__nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.hir-header__link {
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.75));
  text-decoration: none;
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.15s ease;
}

.hir-header__link:hover {
  color: var(--color-iridescent-fade, var(--accent-color, #ec4899));
}

.hir-header__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hir-header__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.55rem 1.35rem;
  background: var(--color-iridescent-fade, var(--accent-color, #ec4899));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 0px;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.hir-header__cta:hover {
  opacity: 0.92;
  transform: translateY(-1px);
}

.hir-header__toggle {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.hir-header__bar {
  width: 20px;
  height: 2px;
  background: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 0;
}

.hir-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 1.5rem 1.5rem;
  background: var(--surface-obsidian, var(--color-obsidian, #ffffff));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 1rem;
}

.hir-header__mobile-link {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 1rem;
}

.hir-header__mobile-cta {
  display: inline-block;
  text-align: center;
  padding: 0.75rem 1.5rem;
  background: var(--color-iridescent-fade, var(--accent-color, #ec4899));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 0px;
  text-decoration: none;
  font-weight: 600;
  margin-top: 0.5rem;
}

@media (max-width: 768px) {
  .hir-header__nav { display: none; }
  .hir-header__toggle { display: flex; }
}
</file>
