          <a href="#hero" className="gbl-header__link">Home</a>
          <a href="#training_zones" className="gbl-header__link">Training Zones</a>
          <a href="#footer" className="gbl-header__link">Contact</a>
        </nav>

        <div className="gbl-header__actions">
          <a href="mailto:climb@gravityboulderlab.com" className="gbl-header__cta">
            Get Day Pass ($22)
          </a>
          <button
            type="button"
            className="gbl-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="gbl-header__bar" />
            <span className="gbl-header__bar" />
            <span className="gbl-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="gbl-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="gbl-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
