import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ana-header${scrolled ? ' ana-header--scrolled' : ''}`} role="banner">
      <div className="ana-header__inner">
        <a href="#" className="ana-header__logo" aria-label="Atelier Nord Architects Home">
          Atelier Nord Architects
        </a>

        <nav className="ana-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ana-header__link">Home</a>
          <a href="#projects" className="ana-header__link">Selected Architecture</a>
          <a href="#footer" className="ana-header__link">Contact</a>
        </nav>

        <div className="ana-header__actions">
          <a href="mailto:studio@ateliernord.arch" className="ana-header__cta">
            View Monograph
          </a>
          <button
            type="button"
            className="ana-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ana-header__bar" />
            <span className="ana-header__bar" />
            <span className="ana-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ana-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="ana-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#projects" className="ana-header__mobile-link" onClick={() => setMenuOpen(false)}>Selected Architecture</a>
          <a href="#footer" className="ana-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:studio@ateliernord.arch" className="ana-header__mobile-cta" onClick={() => setMenuOpen(false)}>View Monograph</a>
        </div>
      )}
    </header>
  );
}
