import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`eae-header${scrolled ? ' eae-header--scrolled' : ''}`} role="banner">
      <div className="eae-header__inner">
        <a href="#" className="eae-header__logo" aria-label="Elysian Amalfi Estates Home">
          Elysian Amalfi Estates
        </a>

        <nav className="eae-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="eae-header__link">Home</a>
          <a href="#estates" className="eae-header__link">Available Estates</a>
          <a href="#footer" className="eae-header__link">Contact</a>
        </nav>

        <div className="eae-header__actions">
          <a href="mailto:estates@elysianamalfi.com" className="eae-header__cta">
            View Private Portfolio
          </a>
          <button
            type="button"
            className="eae-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="eae-header__bar" />
            <span className="eae-header__bar" />
            <span className="eae-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="eae-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="eae-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#estates" className="eae-header__mobile-link" onClick={() => setMenuOpen(false)}>Available Estates</a>
          <a href="#footer" className="eae-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:estates@elysianamalfi.com" className="eae-header__mobile-cta" onClick={() => setMenuOpen(false)}>View Private Portfolio</a>
        </div>
      )}
    </header>
  );
}
