import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`cdv-header${scrolled ? ' cdv-header--scrolled' : ''}`} role="banner">
      <div className="cdv-header__inner">
        <a href="#" className="cdv-header__logo" aria-label="Château De Vence Home">
          Château De Vence
        </a>

        <nav className="cdv-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="cdv-header__link">Home</a>
          <a href="#vintages" className="cdv-header__link">Estate Vintages</a>
          <a href="#footer" className="cdv-header__link">Contact</a>
        </nav>

        <div className="cdv-header__actions">
          <a href="mailto:chateau@chateaudevence.fr" className="cdv-header__cta">
            Estate Allocations
          </a>
          <button
            type="button"
            className="cdv-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="cdv-header__bar" />
            <span className="cdv-header__bar" />
            <span className="cdv-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="cdv-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="cdv-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#vintages" className="cdv-header__mobile-link" onClick={() => setMenuOpen(false)}>Estate Vintages</a>
          <a href="#footer" className="cdv-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:chateau@chateaudevence.fr" className="cdv-header__mobile-cta" onClick={() => setMenuOpen(false)}>Estate Allocations</a>
        </div>
      )}
    </header>
  );
}
</file>
<file path="src/components/Header.css">
.cdv-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  width: 100%;
  background: var(--surface-obsidian, var(--color-obsidian, var(--bg-color, #121316)));
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: all 0.25s ease;
}

.cdv-header--scrolled {
  background: var(--surface-obsidian, var(--color-obsidian, #121316));
  border-bottom-color: rgba(255, 255, 255, 0.18);
}

.cdv-header__inner {
  max-width: var(--page-max-width, 1140px);
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.cdv-header__logo {
  font-family: var(--font-heading, 'Cinzel', sans-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-paper, var(--text-color, #ffffff));
  text-decoration: none;
  letter-spacing: -0.02em;
}

.cdv-header__nav {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.cdv-header__link {
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.75));
  text-decoration: none;
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.15s ease;
}

.cdv-header__link:hover {
  color: var(--color-iridescent-fade, var(--accent-color, #ea2a88));
}

.cdv-header__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.cdv-header__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.55rem 1.35rem;
  background: var(--color-iridescent-fade, var(--accent-color, #ea2a88));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 2px;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.cdv-header__cta:hover {
  opacity: 0.92;
  transform: translateY(-1px);
}

.cdv-header__toggle {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 4px;
}

.cdv-header__bar {
  width: 20px;
  height: 2px;
  background: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 0;
}

.cdv-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 1.5rem 1.5rem;
  background: var(--surface-obsidian, var(--color-obsidian, #121316));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 1rem;
}

.cdv-header__mobile-link {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 1rem;
}

.cdv-header__mobile-cta {
  display: inline-block;
  text-align: center;
  padding: 0.75rem 1.5rem;
  background: var(--color-iridescent-fade, var(--accent-color, #ea2a88));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 2px;
  text-decoration: none;
  font-weight: 600;
  margin-top: 0.5rem;
}

@media (max-width: 768px) {
  .cdv-header__nav { display: none; }
  .cdv-header__toggle { display: flex; }
}
</file>
