          <a href="mailto:stay@shizenonsen.jp" className="sgo-header__cta">
            Reserve Sanctuary Suite
          </a>
          <button
            type="button"
            className="sgo-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
