import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sfe-header${scrolled ? ' sfe-header--scrolled' : ''}`} role="banner">
      <div className="sfe-header__inner">
        <a href="#" className="sfe-header__logo" aria-label="SignFlow Enterprise Home">
          SignFlow Enterprise
        </a>

        <nav className="sfe-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sfe-header__link">Home</a>
          <a href="#signing" className="sfe-header__link">Signing Capabilities</a>
          <a href="#footer" className="sfe-header__link">Contact</a>
        </nav>

        <div className="sfe-header__actions">
          <a href="mailto:support@signflowpro.com" className="sfe-header__cta">
            Sign First Document Free
          </a>
          <button
            type="button"
            className="sfe-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sfe-header__bar" />
            <span className="sfe-header__bar" />
            <span className="sfe-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sfe-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="sfe-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#signing" className="sfe-header__mobile-link" onClick={() => setMenuOpen(false)}>Signing Capabilities</a>
          <a href="#footer" className="sfe-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:support@signflowpro.com" className="sfe-header__mobile-cta" onClick={() => setMenuOpen(false)}>Sign First Document Free</a>
        </div>
      )}
    </header>
  );
}
</file>
