export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`gpr-header${scrolled ? ' gpr-header--scrolled' : ''}`} role="banner">
      <div className="gpr-header__inner">
        <a href="#" className="gpr-header__logo" aria-label="GlobalPay Rails Home">
          GlobalPay Rails
        </a>

        <nav className="gpr-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="gpr-header__link">Home</a>
          <a href="#payout_rails" className="gpr-header__link">Payout Rails</a>
          <a href="#footer" className="gpr-header__link">Contact</a>
        </nav>

        <div className="gpr-header__actions">
          <a href="mailto:support@globalpayrails.com" className="gpr-header__cta">
            Get API Keys
          </a>
          <button
            type="button"
            className="gpr-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="gpr-header__bar" />
            <span className="gpr-header__bar" />
            <span className="gpr-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="gpr-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="gpr-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#payout_rails" className="gpr-header__mobile-link" onClick={() => setMenuOpen(false)}>Payout Rails</a>
