  border-radius: 0;
}

.ils-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 1.5rem 1.5rem;
  background: var(--surface-obsidian, var(--color-obsidian, #0f172a));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 1rem;
}

.ils-header__mobile-link {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 1rem;
}

.ils-header__mobile-cta {
  display: inline-block;
  text-align: center;
  padding: 0.75rem 1.5rem;
  background: var(--color-iridescent-fade, var(--accent-color, #38ea2a));
  color: var(--color-paper, var(--text-color, #ffffff));
  border-radius: 8px;
  text-decoration: none;
  font-weight: 600;
  margin-top: 0.5rem;
}

@media (max-width: 768px) {
  .ils-header__nav { display: none; }
  .ils-header__toggle { display: flex; }
}
